export const ReaderError = class extends YAMLError {
  constructor(name, position, characterCode, encoding, reason) {
    super('');
    this.pyName = name;
    this.position = position;
    this.character = characterCode;
    this.encoding = encoding;
    this.reason = reason;
    this.name = 'ReaderError';
    this.pyClass = 'yaml.reader.ReaderError';
    let hex = characterCode.toString(16);
    while (hex.length < 4) hex = '0' + hex;
    this.message = `unacceptable character #x${hex}: ${reason}\n` +
      `  in "${name}", position ${position}`;
  }
  toString() { return this.message; }
};

