// Character classification helpers. Everything is done with explicit code
// point comparisons so that no regular expressions are required anywhere.

export const NULL = '\0';

/** Split a string into an array of code points (Python str indexing semantics). */
export function toChars(text) {
  return Array.from(text);
}

export function isLineBreak(ch) {
  return ch === '\n' || ch === '\x85' || ch === ' ' || ch === ' ';
}

/** Line break characters plus '\r' and the reader's '\0' sentinel. */
export function isBreakOrZero(ch) {
  return ch === '\0' || ch === '\r' || ch === '\n' || ch === '\x85' ||
    ch === ' ' || ch === ' ';
}

export function isBlank(ch) {
  return ch === ' ' || ch === '\t';
}

export function isBlankOrBreakOrZero(ch) {
  return isBlank(ch) || isBreakOrZero(ch);
}

/** Members of '\0 \t\r\n\x85  '. */
export function isSpaceLike(ch) {
  return isBlankOrBreakOrZero(ch);
}

export function isDigit(ch) {
  return ch >= '0' && ch <= '9';
}

export function isHexDigit(ch) {
  return (ch >= '0' && ch <= '9') || (ch >= 'a' && ch <= 'f') || (ch >= 'A' && ch <= 'F');
}

export function isOctDigit(ch) {
  return ch >= '0' && ch <= '7';
}

export function isBinDigit(ch) {
  return ch === '0' || ch === '1';
}

export function isAscii(ch) {
  return ch !== undefined && ch.codePointAt(0) < 128;
}

/** Letters, digits, '-' and '_': the character set allowed in anchor names. */
export function isAlphaNumeric(ch) {
  if (ch === undefined) return false;
  return (ch >= '0' && ch <= '9') || (ch >= 'A' && ch <= 'Z') ||
    (ch >= 'a' && ch <= 'z') || ch === '-' || ch === '_';
}

/**
 * Printable per PyYAML's Reader.NON_PRINTABLE: tab, LF, CR, the ASCII range
 * 0x20-0x7E, NEL, and the remaining non-surrogate Unicode scalar values.
 */
export function isPrintable(code) {
  if (code === 0x09 || code === 0x0a || code === 0x0d || code === 0x85) return true;
  if (code >= 0x20 && code <= 0x7e) return true;
  if (code >= 0xa0 && code <= 0xd7ff) return true;
  if (code >= 0xe000 && code <= 0xfffd) return true;
  if (code >= 0x10000 && code <= 0x10ffff) return true;
  return false;
}

/**
 * The emitter's notion of a character that survives without escaping:
 * '\n' or the printable ASCII range, extended by the allow_unicode ranges.
 */
export function isAsciiPrintableOrNewline(ch) {
  return ch === '\n' || (ch >= '\x20' && ch <= '\x7E');
}

export function isUnicodeSafe(ch) {
  const code = ch.codePointAt(0);
  if (code === 0x85) return true;
  if (code >= 0xa0 && code <= 0xd7ff) return true;
  if (code >= 0xe000 && code <= 0xfffd) return true;
  if (code >= 0x10000 && code < 0x10ffff) return true;
  return false;
}

/** True when every character of `text` is in `set`. */
export function allIn(text, set) {
  for (const ch of text) if (!set.includes(ch)) return false;
  return true;
}

