// Character stream over an in-memory string, mirroring PyYAML's reader.py for
// the `str` input case (the only case `safe_load(args.a)` exercises).

import { Mark, ReaderError } from './errors.mjs';
import { isPrintable, isLineBreak, toChars } from './chars.mjs';

export class Reader {
  constructor(text) {
    this.name = '<unicode string>';
    this.checkPrintable(text);
    this.buffer = toChars(text);
    this.buffer.push('\0');
    this.pointer = 0;
    this.index = 0;
    this.line = 0;
    this.column = 0;
    this.eof = true;
  }

  checkPrintable(text) {
    const chars = toChars(text);
    for (let i = 0; i < chars.length; i += 1) {
      const code = chars[i].codePointAt(0);
      if (!isPrintable(code)) {
        throw new ReaderError(this.name, i, code, 'unicode',
          'special characters are not allowed');
      }
    }
  }

  peek(index = 0) {
    const ch = this.buffer[this.pointer + index];
    return ch === undefined ? '\0' : ch;
  }

  prefix(length = 1) {
    return this.buffer.slice(this.pointer, this.pointer + length).join('');
  }

  forward(length = 1) {
    while (length) {
      const ch = this.buffer[this.pointer];
      this.pointer += 1;
      this.index += 1;
      if (isLineBreak(ch) || (ch === '\r' && this.buffer[this.pointer] !== '\n')) {
        this.line += 1;
        this.column = 0;
      } else {
        this.column += 1;
      }
      length -= 1;
    }
  }

  getMark() {
    return new Mark(this.name, this.index, this.line, this.column,
      this.buffer, this.pointer);
  }
}

