// Token objects produced by the scanner. `type` is used for dispatch, `id` is
// the human readable name PyYAML puts in error messages.

class Token {
  constructor(type, id, startMark, endMark) {
    this.type = type;
    this.id = id;
    this.startMark = startMark;
    this.endMark = endMark;
  }
}

function simple(type, id) {
  return class extends Token {
    constructor(startMark, endMark) { super(type, id, startMark, endMark); }
  };
}

export const StreamStartToken = class extends Token {
  constructor(startMark, endMark, encoding = null) {
    super('StreamStart', '<stream start>', startMark, endMark);
    this.encoding = encoding;
  }
};

export const StreamEndToken = simple('StreamEnd', '<stream end>');

export const DirectiveToken = class extends Token {
  constructor(name, value, startMark, endMark) {
    super('Directive', '<directive>', startMark, endMark);
    this.dirName = name;
    this.value = value;
  }
};

