// Tokenizer, a direct transliteration of PyYAML's scanner.py.
// All character tests are plain comparisons / substring membership.

import { Reader } from './reader.mjs';
import { ScannerError } from './errors.mjs';
import { isAlphaNumeric, isDigit, isHexDigit } from './chars.mjs';
import { pyRepr } from './repr.mjs';
import {
  StreamStartToken, StreamEndToken, DirectiveToken, DocumentStartToken,
  DocumentEndToken, BlockSequenceStartToken, BlockMappingStartToken,
  BlockEndToken, FlowSequenceStartToken, FlowMappingStartToken,
  FlowSequenceEndToken, FlowMappingEndToken, KeyToken, ValueToken,
  BlockEntryToken, FlowEntryToken, AliasToken, AnchorToken, TagToken,
  ScalarToken,
} from './tokens.mjs';

const NULL_BL_T_LINEBR = '\0 \t\r\n\x85  ';
const NULL_BL_LINEBR = '\0 \r\n\x85  ';
const NULL_OR_LINEBR = '\0\r\n\x85  ';
const FULL_LINEBR = '\r\n\x85  ';
const SPACES_AND_LINEBR = ' \r\n\x85  ';
const HEX_DIGITS = '0123456789ABCDEFabcdef';

const ESCAPE_REPLACEMENTS = new Map([
  ['0', '\0'], ['a', '\x07'], ['b', '\x08'], ['t', '\x09'], ['\t', '\x09'],
  ['n', '\x0A'], ['v', '\x0B'], ['f', '\x0C'], ['r', '\x0D'], ['e', '\x1B'],
  [' ', '\x20'], ['"', '"'], ['\\', '\\'], ['N', '\x85'], ['_', '\xA0'],
  ['L', ' '], ['P', ' '],
]);

const ESCAPE_CODES = new Map([['x', 2], ['u', 4], ['U', 8]]);

class SimpleKey {
  constructor(tokenNumber, required, index, line, column, mark) {
    this.tokenNumber = tokenNumber;
    this.required = required;
    this.index = index;
    this.line = line;
    this.column = column;
    this.mark = mark;
  }
}

function parseHex(text) {
  let value = 0;
  for (const ch of text) {
    let digit;
    if (ch >= '0' && ch <= '9') digit = ch.charCodeAt(0) - 48;
    else if (ch >= 'a' && ch <= 'f') digit = ch.charCodeAt(0) - 87;
    else digit = ch.charCodeAt(0) - 55;
    value = value * 16 + digit;
  }
  return value;
}

function decodeUtf8(codes) {
  const bytes = Uint8Array.from(codes);
  return new TextDecoder('utf-8', { fatal: true }).decode(bytes);
}

export class Scanner {
  constructor(text) {
    this.reader = new Reader(text);
    this.done = false;
    this.flowLevel = 0;
    this.tokens = [];
    this.openEnded = false;
    this.tokensTaken = 0;
    this.indent = -1;
    this.indents = [];
    this.allowSimpleKey = true;
    this.possibleSimpleKeys = new Map();
    this.fetchStreamStart();
  }

  // --- Reader delegation -------------------------------------------------

  peek(index = 0) { return this.reader.peek(index); }
  prefix(length = 1) { return this.reader.prefix(length); }
  forward(length = 1) { this.reader.forward(length); }
  getMark() { return this.reader.getMark(); }
  get column() { return this.reader.column; }
  get line() { return this.reader.line; }
  get index() { return this.reader.index; }

