// Python-compatible repr() for the strings that appear in error messages.

/**
 * Approximates str.isprintable(): everything outside the printable ASCII
 * range is escaped unless it is an ordinary graphic Unicode character.
 * The C* (control/format/surrogate/private/unassigned) and Z[lps] categories
 * are treated as non printable, matching CPython for the characters PyYAML
 * can put in a message.
 */
function isPrintableChar(code) {
  if (code === 0x20) return true;
  if (code < 0x20 || (code >= 0x7f && code <= 0xa0)) return false;
  if (code === 0xad) return false;
  if (code === 0x2028 || code === 0x2029) return false;
  if (code >= 0x2000 && code <= 0x200f) return false;
  if (code >= 0x202a && code <= 0x202f) return false;
  if (code >= 0x2060 && code <= 0x206f) return false;
  if (code === 0x3000 || code === 0x1680 || code === 0x180e) return false;
  if (code >= 0xd800 && code <= 0xdfff) return false;
  if (code >= 0xe000 && code <= 0xf8ff) return false;
  if (code >= 0xfff9 && code <= 0xfffb) return false;
  if (code === 0xfeff) return false;
  return true;
}

function hexEscape(code) {
  if (code <= 0xff) {
    let hex = code.toString(16);
    while (hex.length < 2) hex = '0' + hex;
    return '\\x' + hex;
  }
  if (code <= 0xffff) {
    let hex = code.toString(16);
    while (hex.length < 4) hex = '0' + hex;
    return '\\u' + hex;
  }
  let hex = code.toString(16);
  while (hex.length < 8) hex = '0' + hex;
  return '\\U' + hex;
}

export function pyRepr(text) {
  const value = text === undefined || text === null ? '' : String(text);
  let quote = "'";
  if (value.includes("'") && !value.includes('"')) quote = '"';
  let out = quote;
  for (const ch of value) {
    const code = ch.codePointAt(0);
    if (ch === '\\') out += '\\\\';
    else if (ch === quote) out += '\\' + quote;
    else if (ch === '\n') out += '\\n';
    else if (ch === '\r') out += '\\r';
    else if (ch === '\t') out += '\\t';
    else if (!isPrintableChar(code)) out += hexEscape(code);
    else out += ch;
  }
  return out + quote;
}

