// Event parser, a transliteration of PyYAML's parser.py. Parser states are
// held as method names so the state stack stays easy to follow.

import { Scanner } from './scanner.mjs';
import { ParserError } from './errors.mjs';
import { pyRepr } from './repr.mjs';
import {
  StreamStartEvent, StreamEndEvent, DocumentStartEvent, DocumentEndEvent,
  AliasEvent, ScalarEvent, SequenceStartEvent, SequenceEndEvent,
  MappingStartEvent, MappingEndEvent,
} from './events.mjs';

const DEFAULT_TAGS = new Map([['!', '!'], ['!!', 'tag:yaml.org,2002:']]);

export class Parser {
  constructor(text) {
    this.scanner = new Scanner(text);
    this.currentEvent = null;
    this.yamlVersion = null;
    this.tagHandles = new Map();
    this.states = [];
    this.marks = [];
    this.state = 'parseStreamStart';
  }

  checkToken(...types) { return this.scanner.checkToken(...types); }
  peekToken() { return this.scanner.peekToken(); }
  getToken() { return this.scanner.getToken(); }

  // --- Public event API --------------------------------------------------

  checkEvent(...types) {
    if (this.currentEvent === null && this.state !== null) {
      this.currentEvent = this[this.state]();
    }
    if (this.currentEvent !== null) {
      if (types.length === 0) return true;
      for (const type of types) {
        if (this.currentEvent.type === type) return true;
      }
    }
    return false;
  }

  peekEvent() {
    if (this.currentEvent === null && this.state !== null) {
      this.currentEvent = this[this.state]();
    }
    return this.currentEvent;
  }

  getEvent() {
    if (this.currentEvent === null && this.state !== null) {
      this.currentEvent = this[this.state]();
    }
    const value = this.currentEvent;
    this.currentEvent = null;
    return value;
  }

  // --- Stream / document -------------------------------------------------

  parseStreamStart() {
    const token = this.getToken();
    const event = new StreamStartEvent(token.startMark, token.endMark,
      token.encoding);
    this.state = 'parseImplicitDocumentStart';
    return event;
  }

  parseImplicitDocumentStart() {
    if (!this.checkToken('Directive', 'DocumentStart', 'StreamEnd')) {
      this.tagHandles = new Map(DEFAULT_TAGS);
      const token = this.peekToken();
      const startMark = token.startMark;
      const event = new DocumentStartEvent(startMark, startMark, false);
      this.states.push('parseDocumentEnd');
      this.state = 'parseBlockNode';
      return event;
    }
    return this.parseDocumentStart();
  }

  parseDocumentStart() {
    while (this.checkToken('DocumentEnd')) this.getToken();
    let event;
    if (!this.checkToken('StreamEnd')) {
      let token = this.peekToken();
      const startMark = token.startMark;
      const [version, tags] = this.processDirectives();
      if (!this.checkToken('DocumentStart')) {
        throw new ParserError(null, null,
          `expected '<document start>', but found ${pyRepr(this.peekToken().id)}`,
          this.peekToken().startMark);
      }
      token = this.getToken();
      const endMark = token.endMark;
      event = new DocumentStartEvent(startMark, endMark, true, version, tags);
      this.states.push('parseDocumentEnd');
      this.state = 'parseDocumentContent';
    } else {
      const token = this.getToken();
      event = new StreamEndEvent(token.startMark, token.endMark);
      this.state = null;
    }
    return event;
  }

  parseDocumentEnd() {
    let token = this.peekToken();
    const startMark = token.startMark;
    let endMark = startMark;
    let explicit = false;
    if (this.checkToken('DocumentEnd')) {
      token = this.getToken();
      endMark = token.endMark;
      explicit = true;
    }
    const event = new DocumentEndEvent(startMark, endMark, explicit);
    this.state = 'parseDocumentStart';
    return event;
  }

  parseDocumentContent() {
    if (this.checkToken('Directive', 'DocumentStart', 'DocumentEnd', 'StreamEnd')) {
      const event = this.processEmptyScalar(this.peekToken().startMark);
      this.state = this.states.pop();
      return event;
    }
    return this.parseBlockNode();
  }

  processDirectives() {
    this.yamlVersion = null;
    this.tagHandles = new Map();
    while (this.checkToken('Directive')) {
      const token = this.getToken();
      if (token.dirName === 'YAML') {
        if (this.yamlVersion !== null) {
          throw new ParserError(null, null, 'found duplicate YAML directive',
            token.startMark);
        }
        const [major] = token.value;
        if (major !== 1) {
          throw new ParserError(null, null,
            'found incompatible YAML document (version 1.* is required)',
            token.startMark);
        }
        this.yamlVersion = token.value;
      } else if (token.dirName === 'TAG') {
        const [handle, prefix] = token.value;
        if (this.tagHandles.has(handle)) {
          throw new ParserError(null, null,
            `duplicate tag handle ${pyRepr(handle)}`, token.startMark);
        }
        this.tagHandles.set(handle, prefix);
      }
    }
    let value;
    if (this.tagHandles.size) value = [this.yamlVersion, new Map(this.tagHandles)];
    else value = [this.yamlVersion, null];
    for (const [key, prefix] of DEFAULT_TAGS) {
      if (!this.tagHandles.has(key)) this.tagHandles.set(key, prefix);
    }
    return value;
  }

  // --- Nodes -------------------------------------------------------------

  parseBlockNode() { return this.parseNode(true, false); }
  parseFlowNode() { return this.parseNode(false, false); }
  parseBlockNodeOrIndentlessSequence() { return this.parseNode(true, true); }

  parseNode(block = false, indentlessSequence = false) {
    if (this.checkToken('Alias')) {
      const token = this.getToken();
      const event = new AliasEvent(token.value, token.startMark, token.endMark);
      this.state = this.states.pop();
      return event;
    }
    let anchor = null;
    let tag = null;
    let startMark = null;
    let endMark = null;
    let tagMark = null;
    if (this.checkToken('Anchor')) {
      let token = this.getToken();
      startMark = token.startMark;
      endMark = token.endMark;
      anchor = token.value;
      if (this.checkToken('Tag')) {
        token = this.getToken();
        tagMark = token.startMark;
        endMark = token.endMark;
        tag = token.value;
      }
    } else if (this.checkToken('Tag')) {
      let token = this.getToken();
      startMark = token.startMark;
      tagMark = token.startMark;
      endMark = token.endMark;
      tag = token.value;
      if (this.checkToken('Anchor')) {
        token = this.getToken();
        endMark = token.endMark;
        anchor = token.value;
      }
    }
    if (tag !== null) {
      const [handle, suffix] = tag;
      if (handle !== null) {
        if (!this.tagHandles.has(handle)) {
          throw new ParserError('while parsing a node', startMark,
            `found undefined tag handle ${pyRepr(handle)}`, tagMark);
        }
        tag = this.tagHandles.get(handle) + suffix;
      } else {
        tag = suffix;
      }
    }
    if (startMark === null) {
      startMark = this.peekToken().startMark;
      endMark = startMark;
    }
    let event = null;
    let implicit = tag === null || tag === '!';
    if (indentlessSequence && this.checkToken('BlockEntry')) {
      endMark = this.peekToken().endMark;
      event = new SequenceStartEvent(anchor, tag, implicit, startMark, endMark);
      this.state = 'parseIndentlessSequenceEntry';
      return event;
    }
    if (this.checkToken('Scalar')) {
      const token = this.getToken();
      endMark = token.endMark;
      let scalarImplicit;
      if ((token.plain && tag === null) || tag === '!') {
        scalarImplicit = [true, false];
      } else if (tag === null) {
        scalarImplicit = [false, true];
      } else {
        scalarImplicit = [false, false];
      }
      event = new ScalarEvent(anchor, tag, scalarImplicit, token.value,
        startMark, endMark, token.style);
      this.state = this.states.pop();
    } else if (this.checkToken('FlowSequenceStart')) {
      endMark = this.peekToken().endMark;
      event = new SequenceStartEvent(anchor, tag, implicit, startMark, endMark,
        true);
      this.state = 'parseFlowSequenceFirstEntry';
    } else if (this.checkToken('FlowMappingStart')) {
      endMark = this.peekToken().endMark;
      event = new MappingStartEvent(anchor, tag, implicit, startMark, endMark,
        true);
      this.state = 'parseFlowMappingFirstKey';
    } else if (block && this.checkToken('BlockSequenceStart')) {
      endMark = this.peekToken().startMark;
      event = new SequenceStartEvent(anchor, tag, implicit, startMark, endMark,
        false);
      this.state = 'parseBlockSequenceFirstEntry';
    } else if (block && this.checkToken('BlockMappingStart')) {
      endMark = this.peekToken().startMark;
      event = new MappingStartEvent(anchor, tag, implicit, startMark, endMark,
        false);
      this.state = 'parseBlockMappingFirstKey';
    } else if (anchor !== null || tag !== null) {
      event = new ScalarEvent(anchor, tag, [implicit, false], '', startMark,
        endMark);
      this.state = this.states.pop();
    } else {
      const node = block ? 'block' : 'flow';
      const token = this.peekToken();
      throw new ParserError(`while parsing a ${node} node`, startMark,
        `expected the node content, but found ${pyRepr(token.id)}`,
        token.startMark);
    }
    return event;
  }

  // --- Block collections -------------------------------------------------

  parseBlockSequenceFirstEntry() {
    const token = this.getToken();
    this.marks.push(token.startMark);
    return this.parseBlockSequenceEntry();
  }

  parseBlockSequenceEntry() {
    if (this.checkToken('BlockEntry')) {
      const token = this.getToken();
      if (!this.checkToken('BlockEntry', 'BlockEnd')) {
        this.states.push('parseBlockSequenceEntry');
        return this.parseBlockNode();
      }
      this.state = 'parseBlockSequenceEntry';
      return this.processEmptyScalar(token.endMark);
    }
    if (!this.checkToken('BlockEnd')) {
      const token = this.peekToken();
      throw new ParserError('while parsing a block collection',
        this.marks[this.marks.length - 1],
        `expected <block end>, but found ${pyRepr(token.id)}`, token.startMark);
    }
    const token = this.getToken();
    const event = new SequenceEndEvent(token.startMark, token.endMark);
    this.state = this.states.pop();
    this.marks.pop();
    return event;
  }

  parseIndentlessSequenceEntry() {
    if (this.checkToken('BlockEntry')) {
      const token = this.getToken();
      if (!this.checkToken('BlockEntry', 'Key', 'Value', 'BlockEnd')) {
        this.states.push('parseIndentlessSequenceEntry');
        return this.parseBlockNode();
      }
      this.state = 'parseIndentlessSequenceEntry';
      return this.processEmptyScalar(token.endMark);
    }
    const token = this.peekToken();
    const event = new SequenceEndEvent(token.startMark, token.startMark);
    this.state = this.states.pop();
    return event;
  }

  parseBlockMappingFirstKey() {
    const token = this.getToken();
    this.marks.push(token.startMark);
    return this.parseBlockMappingKey();
  }

  parseBlockMappingKey() {
    if (this.checkToken('Key')) {
      const token = this.getToken();
      if (!this.checkToken('Key', 'Value', 'BlockEnd')) {
        this.states.push('parseBlockMappingValue');
        return this.parseBlockNodeOrIndentlessSequence();
      }
      this.state = 'parseBlockMappingValue';
      return this.processEmptyScalar(token.endMark);
    }
    if (!this.checkToken('BlockEnd')) {
      const token = this.peekToken();
      throw new ParserError('while parsing a block mapping',
        this.marks[this.marks.length - 1],
        `expected <block end>, but found ${pyRepr(token.id)}`, token.startMark);
    }
    const token = this.getToken();
    const event = new MappingEndEvent(token.startMark, token.endMark);
    this.state = this.states.pop();
    this.marks.pop();
    return event;
  }

  parseBlockMappingValue() {
    if (this.checkToken('Value')) {
      const token = this.getToken();
      if (!this.checkToken('Key', 'Value', 'BlockEnd')) {
