// Hand written matchers for the implicit tag patterns of PyYAML's resolver and
// for the timestamp grammar used by its constructor. Each function mirrors the
// corresponding regular expression, anchored at both ends.

import { isDigit, isHexDigit } from './chars.mjs';

const BOOL_VALUES = ['yes', 'Yes', 'YES', 'no', 'No', 'NO',
  'true', 'True', 'TRUE', 'false', 'False', 'FALSE',
  'on', 'On', 'ON', 'off', 'Off', 'OFF'];

const NULL_VALUES = ['', '~', 'null', 'Null', 'NULL'];

function isSign(ch) { return ch === '-' || ch === '+'; }
function isDigitOrUnderscore(ch) { return isDigit(ch) || ch === '_'; }

/** Consume `[0-9_]*` from `i`, returning the new index. */
function skipDigitsOrUnderscores(s, i) {
  let j = i;
  while (j < s.length && isDigitOrUnderscore(s[j])) j += 1;
  return j;
}

/** `(?:[eE][-+][0-9]+)?` — returns the new index, or -1 on a malformed exponent. */
function matchOptionalExponent(s, i) {
  if (i >= s.length) return i;
  if (s[i] !== 'e' && s[i] !== 'E') return i;
  let j = i + 1;
