// Implicit tag resolution (PyYAML resolver.py, Resolver class).

import {
  matchBool, matchFloat, matchInt, matchMerge, matchNull, matchTimestamp,
  matchValueTag, matchYamlTag,
} from './patterns.mjs';

export const DEFAULT_SCALAR_TAG = 'tag:yaml.org,2002:str';
export const DEFAULT_SEQUENCE_TAG = 'tag:yaml.org,2002:seq';
export const DEFAULT_MAPPING_TAG = 'tag:yaml.org,2002:map';

// Registration order matters: for a shared first character the resolver that
// was added first wins (this is why '1.5' resolves to float, not int).
const IMPLICIT_RESOLVERS = [
  { tag: 'tag:yaml.org,2002:bool', first: 'yYnNtTfFoO', match: matchBool },
  { tag: 'tag:yaml.org,2002:float', first: '-+0123456789.', match: matchFloat },
  { tag: 'tag:yaml.org,2002:int', first: '-+0123456789', match: matchInt },
  { tag: 'tag:yaml.org,2002:merge', first: '<', match: matchMerge },
  { tag: 'tag:yaml.org,2002:null', first: '~nN�', match: matchNull },
  { tag: 'tag:yaml.org,2002:timestamp', first: '0123456789', match: matchTimestamp },
  { tag: 'tag:yaml.org,2002:value', first: '=', match: matchValueTag },
  { tag: 'tag:yaml.org,2002:yaml', first: '!&*', match: matchYamlTag },
];

// PyYAML registers the null resolver for the empty string as well; '�'
// above stands for that bucket so the table can stay a plain string.
const EMPTY_BUCKET = '�';

export class Resolver {
  /**
   * @param {'scalar'|'sequence'|'mapping'} kind
   * @param {string} value
   * @param {[boolean, boolean]} implicit
   */
  resolve(kind, value, implicit) {
    if (kind === 'scalar' && implicit[0]) {
      const bucket = value === '' ? EMPTY_BUCKET : value[0];
      for (const resolver of IMPLICIT_RESOLVERS) {
        if (resolver.first.includes(bucket) && resolver.match(value)) {
          return resolver.tag;
        }
      }
    }
    if (kind === 'scalar') return DEFAULT_SCALAR_TAG;
    if (kind === 'sequence') return DEFAULT_SEQUENCE_TAG;
    if (kind === 'mapping') return DEFAULT_MAPPING_TAG;
    return null;
  }
}

