// Python value model. Ints are BigInt, floats are Number, str is string,
// list is Array; the remaining Python types get a small wrapper class each.

import { PyTypeError, PyValueError } from './errors.mjs';

export class PyTuple {
  constructor(items) { this.items = items; }
}

export class PyBytes {
  constructor(bytes) { this.bytes = bytes; }
}

export class PyDate {
  constructor(year, month, day) {
    validateDate(year, month, day);
    this.year = year;
    this.month = month;
    this.day = day;
  }

  isoformat() {
    return `${pad(this.year, 4)}-${pad(this.month, 2)}-${pad(this.day, 2)}`;
  }
}

export class PyDateTime {
  constructor(year, month, day, hour, minute, second, microsecond, offsetMinutes) {
    validateDate(year, month, day);
    if (hour < 0 || hour > 23) throw new PyValueError('hour must be in 0..23');
    if (minute < 0 || minute > 59) throw new PyValueError('minute must be in 0..59');
    if (second < 0 || second > 59) throw new PyValueError('second must be in 0..59');
    if (offsetMinutes !== null && Math.abs(offsetMinutes) >= 1440) {
      throw new PyValueError(
        'offset must be a timedelta strictly between -timedelta(hours=24) and timedelta(hours=24)');
    }
    this.year = year;
    this.month = month;
    this.day = day;
    this.hour = hour;
    this.minute = minute;
    this.second = second;
    this.microsecond = microsecond;
    this.offsetMinutes = offsetMinutes;
  }

  isoformat(sep = 'T') {
    let text = `${pad(this.year, 4)}-${pad(this.month, 2)}-${pad(this.day, 2)}${sep}` +
      `${pad(this.hour, 2)}:${pad(this.minute, 2)}:${pad(this.second, 2)}`;
    if (this.microsecond) text += '.' + pad(this.microsecond, 6);
    if (this.offsetMinutes !== null) {
      const sign = this.offsetMinutes < 0 ? '-' : '+';
      const total = Math.abs(this.offsetMinutes);
      text += `${sign}${pad(Math.floor(total / 60), 2)}:${pad(total % 60, 2)}`;
    }
    return text;
  }

  /** Total minutes since the epoch-independent civil time, for ordering. */
  ordinalMinutes() {
    return daysFromCivil(this.year, this.month, this.day) * 1440 +
      this.hour * 60 + this.minute - (this.offsetMinutes === null ? 0 : this.offsetMinutes);
  }
}

function pad(value, width) {
  let text = String(Math.trunc(Math.abs(value)));
  while (text.length < width) text = '0' + text;
  return (value < 0 ? '-' : '') + text;
}

function isLeapYear(year) {
  return (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
}

function daysInMonth(year, month) {
  const lengths = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (month === 2 && isLeapYear(year)) return 29;
  return lengths[month - 1];
}

function validateDate(year, month, day) {
  if (year < 1 || year > 9999) throw new PyValueError('year is out of range');
  if (month < 1 || month > 12) throw new PyValueError('month must be in 1..12');
  if (day < 1 || day > daysInMonth(year, month)) {
    throw new PyValueError('day is out of range for month');
  }
}

function daysFromCivil(year, month, day) {
  let days = 0;
  for (let y = 1; y < year; y += 1) days += isLeapYear(y) ? 366 : 365;
  for (let m = 1; m < month; m += 1) days += daysInMonth(year, m);
  return days + day - 1;
}

// --- Dict / set with Python hashing semantics ---------------------------

let nextUnhashableId = 0;

/**
 * Canonical lookup key reproducing Python equality for hashable values:
 * True == 1 == 1.0 share a slot, strings and numbers never collide.
 */
export function keyOf(value) {
  if (value === null) return 'none';
  if (typeof value === 'boolean') return 'num:' + (value ? '1' : '0');
  if (typeof value === 'bigint') return 'num:' + value.toString();
  if (typeof value === 'number') {
    if (Number.isNaN(value)) {
      nextUnhashableId += 1;
      return 'nan:' + nextUnhashableId;
    }
    if (Number.isInteger(value)) return 'num:' + BigInt(value).toString();
    return 'num:' + floatRepr(value);
  }
  if (typeof value === 'string') return 'str:' + value;
  if (value instanceof PyBytes) {
    let hex = '';
    for (const byte of value.bytes) hex += pad(byte.toString(16), 2);
    return 'bytes:' + hex;
  }
  if (value instanceof PyTuple) {
    return 'tuple:(' + value.items.map(keyOf).join(',') + ')';
  }
  if (value instanceof PyDate) return 'date:' + value.isoformat();
  if (value instanceof PyDateTime) return 'datetime:' + value.isoformat();
  return null;
}

export function isHashable(value) {
  return keyOf(value) !== null;
}

/** Insertion ordered mapping keyed by Python equality. */
export class PyDict {
  constructor() {
    this.entries = new Map();
  }

  get size() { return this.entries.size; }

  set(key, value) {
    const id = keyOf(key);
    const existing = this.entries.get(id);
    if (existing !== undefined) {
      existing.value = value;
      return;
    }
    this.entries.set(id, { key, value });
  }

  has(key) { return this.entries.has(keyOf(key)); }

  get(key) {
    const entry = this.entries.get(keyOf(key));
    return entry === undefined ? undefined : entry.value;
  }

  update(other) {
    for (const [key, value] of other.items()) this.set(key, value);
  }

  *items() {
    for (const entry of this.entries.values()) yield [entry.key, entry.value];
  }

  itemList() { return Array.from(this.items()); }
}

/** Python set, modelled as a dict with null values (as PyYAML does). */
export class PySet {
  constructor() {
    this.dict = new PyDict();
  }

  get size() { return this.dict.size; }
  add(key) { this.dict.set(key, null); }
  update(other) {
    for (const [key] of other.items()) this.add(key);
  }
  *values() {
    for (const [key] of this.dict.items()) yield key;
  }
}

