  itemList() { return Array.from(this.items()); }
}

/** Python set, modelled as a dict with null values (as PyYAML does). */
export class PySet {
  constructor() {
    this.dict = new PyDict();
  }

  get size() { return this.dict.size; }
  add(key) { this.dict.set(key, null); }
  update(other) {
    for (const [key] of other.items()) this.add(key);
  }
  *values() {
    for (const [key] of this.dict.items()) yield key;
  }
}

// --- Comparison (for sort_keys) -----------------------------------------

function isNumeric(value) {
  return typeof value === 'bigint' || typeof value === 'number' ||
    typeof value === 'boolean';
}

function numericValue(value) {
  if (typeof value === 'boolean') return value ? 1 : 0;
  if (typeof value === 'bigint') return value;
  return value;
}

function compareNumeric(a, b) {
  const x = numericValue(a);
  const y = numericValue(b);
  if (typeof x === 'bigint' && typeof y === 'bigint') {
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
  }
  const fx = typeof x === 'bigint' ? Number(x) : x;
  const fy = typeof y === 'bigint' ? Number(y) : y;
  if (Number.isNaN(fx) || Number.isNaN(fy)) return 1;
  if (fx < fy) return -1;
  if (fx > fy) return 1;
  return 0;
}

function typeName(value) {
  if (value === null) return 'NoneType';
  if (typeof value === 'boolean') return 'bool';
  if (typeof value === 'bigint') return 'int';
  if (typeof value === 'number') return 'float';
  if (typeof value === 'string') return 'str';
  if (Array.isArray(value)) return 'list';
  if (value instanceof PyTuple) return 'tuple';
  if (value instanceof PyBytes) return 'bytes';
  if (value instanceof PyDict) return 'dict';
  if (value instanceof PySet) return 'set';
  if (value instanceof PyDate) return 'datetime.date';
  if (value instanceof PyDateTime) return 'datetime.datetime';
  return 'object';
}

function unorderable(a, b) {
  return new PyTypeError(
    `'<' not supported between instances of '${typeName(a)}' and '${typeName(b)}'`);
}

/** Python's `<` ordering; throws PyTypeError for unorderable pairs. */
export function pyCompare(a, b) {
  if (isNumeric(a) && isNumeric(b)) return compareNumeric(a, b);
  if (typeof a === 'string' && typeof b === 'string') {
    const ca = Array.from(a);
    const cb = Array.from(b);
    const length = Math.min(ca.length, cb.length);
    for (let i = 0; i < length; i += 1) {
      const x = ca[i].codePointAt(0);
      const y = cb[i].codePointAt(0);
      if (x !== y) return x < y ? -1 : 1;
    }
    if (ca.length === cb.length) return 0;
    return ca.length < cb.length ? -1 : 1;
  }
  if (a instanceof PyBytes && b instanceof PyBytes) {
    const length = Math.min(a.bytes.length, b.bytes.length);
    for (let i = 0; i < length; i += 1) {
      if (a.bytes[i] !== b.bytes[i]) return a.bytes[i] < b.bytes[i] ? -1 : 1;
    }
    if (a.bytes.length === b.bytes.length) return 0;
    return a.bytes.length < b.bytes.length ? -1 : 1;
  }
  if (a instanceof PyTuple && b instanceof PyTuple) {
    return compareSequences(a.items, b.items);
  }
  if (Array.isArray(a) && Array.isArray(b)) return compareSequences(a, b);
  if (a instanceof PyDate && b instanceof PyDate) {
    const x = daysFromCivil(a.year, a.month, a.day);
    const y = daysFromCivil(b.year, b.month, b.day);
    return x === y ? 0 : (x < y ? -1 : 1);
  }
  if (a instanceof PyDateTime && b instanceof PyDateTime) {
    if ((a.offsetMinutes === null) !== (b.offsetMinutes === null)) {
      throw new PyTypeError("can't compare offset-naive and offset-aware datetimes");
    }
    const x = a.ordinalMinutes() * 60 + a.second;
    const y = b.ordinalMinutes() * 60 + b.second;
    if (x !== y) return x < y ? -1 : 1;
    if (a.microsecond !== b.microsecond) {
      return a.microsecond < b.microsecond ? -1 : 1;
    }
    return 0;
  }
  throw unorderable(a, b);
}

function compareSequences(left, right) {
  const length = Math.min(left.length, right.length);
  for (let i = 0; i < length; i += 1) {
    const order = pyCompare(left[i], right[i]);
    if (order !== 0) return order;
  }
  if (left.length === right.length) return 0;
  return left.length < right.length ? -1 : 1;
}

// --- repr(float) --------------------------------------------------------

/**
 * CPython's repr for finite floats: shortest round-tripping digits, switching
 * to exponential notation when the decimal point lands outside (-4, 16].
 */
export function floatRepr(value) {
  if (Number.isNaN(value)) return 'nan';
  if (value === Infinity) return 'inf';
  if (value === -Infinity) return '-inf';
  const negative = value < 0 || Object.is(value, -0);
  const magnitude = Math.abs(value);
  if (magnitude === 0) return negative ? '-0.0' : '0.0';

  const exponential = magnitude.toExponential();
  const eIndex = exponential.indexOf('e');
  const mantissa = exponential.slice(0, eIndex);
  const exponent = Number.parseInt(exponential.slice(eIndex + 1), 10);
  const digits = mantissa.split('.').join('');
  const decpt = exponent + 1;

  let text;
  if (decpt > -4 && decpt <= 16) {
    if (decpt <= 0) {
      text = '0.' + '0'.repeat(-decpt) + digits;
    } else if (decpt >= digits.length) {
      text = digits + '0'.repeat(decpt - digits.length) + '.0';
    } else {
      text = digits.slice(0, decpt) + '.' + digits.slice(decpt);
    }
  } else {
    const rest = digits.slice(1);
    const expValue = decpt - 1;
    const expSign = expValue < 0 ? '-' : '+';
    text = digits[0] + (rest ? '.' + rest : '') + 'e' + expSign +
      pad(Math.abs(expValue), 2);
  }
  return negative ? '-' + text : text;
}

// --- base64 -------------------------------------------------------------

const B64_ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';

/** base64.encodebytes: 76 character lines, each terminated by a newline. */
export function encodeBase64Lines(bytes) {
  let encoded = '';
  for (let i = 0; i < bytes.length; i += 3) {
    const b0 = bytes[i];
    const b1 = i + 1 < bytes.length ? bytes[i + 1] : 0;
    const b2 = i + 2 < bytes.length ? bytes[i + 2] : 0;
    encoded += B64_ALPHABET[b0 >> 2];
    encoded += B64_ALPHABET[((b0 & 0x03) << 4) | (b1 >> 4)];
    encoded += i + 1 < bytes.length ? B64_ALPHABET[((b1 & 0x0f) << 2) | (b2 >> 6)] : '=';
    encoded += i + 2 < bytes.length ? B64_ALPHABET[b2 & 0x3f] : '=';
  }
  let out = '';
  for (let i = 0; i < encoded.length; i += 76) {
    out += encoded.slice(i, i + 76) + '\n';
  }
  return out;
}

/**
 * base64.decodebytes: ignores characters outside the alphabet, and rejects
 * data whose significant length is not a multiple of four.
 */
export function decodeBase64(text) {
  const values = [];
  let padding = 0;
  for (const ch of text) {
    if (ch === '=') {
      padding += 1;
      values.push(0);
      continue;
    }
    const index = B64_ALPHABET.indexOf(ch);
    if (index >= 0) {
      if (padding) throw new PyValueError('Invalid base64-encoded string');
      values.push(index);
    }
  }
  if (values.length % 4 !== 0) {
    throw new PyValueError('Invalid base64-encoded string: number of data characters ' +
      `(${values.length - padding}) cannot be 1 more than a multiple of 4`);
  }
  const bytes = [];
  for (let i = 0; i < values.length; i += 4) {
    const triple = (values[i] << 18) | (values[i + 1] << 12) |
      (values[i + 2] << 6) | values[i + 3];
    bytes.push((triple >> 16) & 0xff, (triple >> 8) & 0xff, triple & 0xff);
  }
  let drop = 0;
  if (padding) drop = padding % 4;
  return Uint8Array.from(drop ? bytes.slice(0, bytes.length - drop) : bytes);
}

