// Node graph composer (PyYAML composer.py).

import { Parser } from './parser.mjs';
import { Resolver } from './resolver.mjs';
import { ComposerError } from './errors.mjs';
import { pyRepr } from './repr.mjs';
import { ScalarNode, SequenceNode, MappingNode } from './nodes.mjs';

export class Composer {
  constructor(text) {
    this.parser = new Parser(text);
    this.resolver = new Resolver();
    this.anchors = new Map();
  }

  checkEvent(...types) { return this.parser.checkEvent(...types); }
  peekEvent() { return this.parser.peekEvent(); }
  getEvent() { return this.parser.getEvent(); }
  resolve(kind, value, implicit) { return this.resolver.resolve(kind, value, implicit); }

  checkNode() {
    if (this.checkEvent('StreamStart')) this.getEvent();
    return !this.checkEvent('StreamEnd');
  }

  getNode() {
    if (!this.checkEvent('StreamEnd')) return this.composeDocument();
    return null;
  }

  getSingleNode() {
    this.getEvent();
    let document = null;
    if (!this.checkEvent('StreamEnd')) document = this.composeDocument();
    if (!this.checkEvent('StreamEnd')) {
      const event = this.getEvent();
      throw new ComposerError('expected a single document in the stream',
        document.startMark, 'but found another document', event.startMark);
    }
    this.getEvent();
    return document;
  }

  composeDocument() {
    this.getEvent();
    const node = this.composeNode(null, null);
    this.getEvent();
    this.anchors = new Map();
    return node;
  }

  composeNode(parent, index) {
    if (this.checkEvent('Alias')) {
      const event = this.getEvent();
      const anchor = event.anchor;
      if (!this.anchors.has(anchor)) {
        throw new ComposerError(null, null,
          `found undefined alias ${pyRepr(anchor)}`, event.startMark);
      }
      return this.anchors.get(anchor);
    }
    const event = this.peekEvent();
    const anchor = event.anchor === undefined ? null : event.anchor;
    if (anchor !== null && this.anchors.has(anchor)) {
      throw new ComposerError(
        `found duplicate anchor ${pyRepr(anchor)}; first occurrence`,
        this.anchors.get(anchor).startMark, 'second occurrence', event.startMark);
    }
    let node = null;
    if (this.checkEvent('Scalar')) node = this.composeScalarNode(anchor);
    else if (this.checkEvent('SequenceStart')) node = this.composeSequenceNode(anchor);
    else if (this.checkEvent('MappingStart')) node = this.composeMappingNode(anchor);
    return node;
  }

  composeScalarNode(anchor) {
    const event = this.getEvent();
    let tag = event.tag;
    if (tag === null || tag === '!') {
      tag = this.resolve('scalar', event.value, event.implicit);
    }
    const node = new ScalarNode(tag, event.value, event.startMark, event.endMark,
      event.style);
    if (anchor !== null) this.anchors.set(anchor, node);
    return node;
  }

  composeSequenceNode(anchor) {
    const startEvent = this.getEvent();
    let tag = startEvent.tag;
    if (tag === null || tag === '!') {
      tag = this.resolve('sequence', null, startEvent.implicit);
    }
    const node = new SequenceNode(tag, [], startEvent.startMark, null,
      startEvent.flowStyle);
    if (anchor !== null) this.anchors.set(anchor, node);
    let index = 0;
    while (!this.checkEvent('SequenceEnd')) {
      node.value.push(this.composeNode(node, index));
      index += 1;
    }
    const endEvent = this.getEvent();
    node.endMark = endEvent.endMark;
    return node;
  }

  composeMappingNode(anchor) {
    const startEvent = this.getEvent();
    let tag = startEvent.tag;
    if (tag === null || tag === '!') {
      tag = this.resolve('mapping', null, startEvent.implicit);
    }
    const node = new MappingNode(tag, [], startEvent.startMark, null,
      startEvent.flowStyle);
    if (anchor !== null) this.anchors.set(anchor, node);
    while (!this.checkEvent('MappingEnd')) {
      const itemKey = this.composeNode(node, null);
      const itemValue = this.composeNode(node, itemKey);
      node.value.push([itemKey, itemValue]);
    }
    const endEvent = this.getEvent();
    node.endMark = endEvent.endMark;
    return node;
  }
}

