// SafeConstructor: turns the node graph into Python values (constructor.py).

import { Composer } from './composer.mjs';
import { ConstructorError, PyValueError } from './errors.mjs';
import { pyRepr } from './repr.mjs';
import { parseTimestamp } from './patterns.mjs';
import {
  PyDict, PySet, PyTuple, PyBytes, PyDate, PyDateTime, isHashable,
  decodeBase64,
} from './pyvalues.mjs';

const BOOL_VALUES = new Map([
  ['yes', true], ['no', false], ['true', true], ['false', false],
  ['on', true], ['off', false],
]);

class PyKeyError extends Error {
  constructor(key) {
    super(pyRepr(key));
    this.name = 'KeyError';
    this.pyClass = 'KeyError';
  }
}

class PyIndexError extends Error {
  constructor(message) {
    super(message);
    this.name = 'IndexError';
    this.pyClass = 'IndexError';
  }
}

class PyAttributeError extends Error {
  constructor(message) {
    super(message);
    this.name = 'AttributeError';
    this.pyClass = 'AttributeError';
  }
}

function isGenerator(value) {
  return value !== null && typeof value === 'object' &&
    typeof value.next === 'function' && typeof value.throw === 'function';
}

/** int(text, base) with Python's arbitrary precision. */
function parseBigInt(text, base) {
  if (text.length === 0) {
    throw new PyValueError(
      `invalid literal for int() with base ${base}: ${pyRepr(text)}`);
  }
  const bigBase = BigInt(base);
  let result = 0n;
  for (const ch of text) {
    let digit;
    if (ch >= '0' && ch <= '9') digit = ch.charCodeAt(0) - 48;
    else if (ch >= 'a' && ch <= 'z') digit = ch.charCodeAt(0) - 87;
    else if (ch >= 'A' && ch <= 'Z') digit = ch.charCodeAt(0) - 55;
    else digit = 99;
    if (digit >= base) {
      throw new PyValueError(
        `invalid literal for int() with base ${base}: ${pyRepr(text)}`);
    }
    result = result * bigBase + BigInt(digit);
  }
  return result;
}

/** float(text) following Python's accepted grammar. */
function parseFloat_(text) {
  const raw = text;
  const s = text.trim();
  const fail = () => new PyValueError(
    `could not convert string to float: ${pyRepr(raw)}`);
  let i = 0;
  let sign = 1;
  if (s[i] === '+' || s[i] === '-') {
    if (s[i] === '-') sign = -1;
    i += 1;
  }
  const rest = s.slice(i).toLowerCase();
  if (rest === 'inf' || rest === 'infinity') return sign * Infinity;
  if (rest === 'nan') return NaN;

  let digitsBefore = 0;
  let digitsAfter = 0;
  let j = i;
  while (j < s.length && s[j] >= '0' && s[j] <= '9') { j += 1; digitsBefore += 1; }
  if (s[j] === '.') {
    j += 1;
    while (j < s.length && s[j] >= '0' && s[j] <= '9') { j += 1; digitsAfter += 1; }
  }
  if (digitsBefore + digitsAfter === 0) throw fail();
  if (j < s.length && (s[j] === 'e' || s[j] === 'E')) {
    j += 1;
    if (s[j] === '+' || s[j] === '-') j += 1;
    let expDigits = 0;
    while (j < s.length && s[j] >= '0' && s[j] <= '9') { j += 1; expDigits += 1; }
    if (expDigits === 0) throw fail();
  }
  if (j !== s.length) throw fail();
  return sign * Number(s.slice(i));
}

export class SafeConstructor {
  constructor(text) {
    this.composer = new Composer(text);
    this.constructedObjects = new Map();
    this.recursiveObjects = new Map();
    this.stateGenerators = [];
    this.deepConstruct = false;
  }

  // --- Document level ----------------------------------------------------

  getSingleData() {
    const node = this.composer.getSingleNode();
    if (node !== null) return this.constructDocument(node);
    return null;
  }

  constructDocument(node) {
    const data = this.constructObject(node);
    while (this.stateGenerators.length) {
      const generators = this.stateGenerators;
      this.stateGenerators = [];
      for (const generator of generators) {
        for (const dummy of generator) { /* drain */ }
      }
    }
    this.constructedObjects = new Map();
    this.recursiveObjects = new Map();
    this.deepConstruct = false;
    return data;
  }

  constructObject(node, deep = false) {
    if (this.constructedObjects.has(node)) return this.constructedObjects.get(node);
    let oldDeep;
    if (deep) {
      oldDeep = this.deepConstruct;
      this.deepConstruct = true;
    }
    if (this.recursiveObjects.has(node)) {
      throw new ConstructorError(null, null, 'found unconstructable recursive node',
        node.startMark);
    }
    this.recursiveObjects.set(node, null);

    const constructor = CONSTRUCTORS.get(node.tag) || constructUndefined;
    let data = constructor.call(this, node);
    if (isGenerator(data)) {
      const generator = data;
      data = generator.next().value;
      if (this.deepConstruct) {
        for (const dummy of generator) { /* drain */ }
      } else {
        this.stateGenerators.push(generator);
      }
    }
    this.constructedObjects.set(node, data);
    this.recursiveObjects.delete(node);
    if (deep) this.deepConstruct = oldDeep;
    return data;
  }

  // --- Generic node helpers ----------------------------------------------

  constructScalar(node) {
    if (node.kind === 'mapping') {
      for (const [keyNode, valueNode] of node.value) {
        if (keyNode.tag === 'tag:yaml.org,2002:value') {
          return this.constructScalar(valueNode);
        }
      }
    }
    if (node.kind !== 'scalar') {
      throw new ConstructorError(null, null,
        `expected a scalar node, but found ${node.kind}`, node.startMark);
    }
    return node.value;
  }

  constructSequence(node, deep = false) {
    if (node.kind !== 'sequence') {
      throw new ConstructorError(null, null,
        `expected a sequence node, but found ${node.kind}`, node.startMark);
    }
    return node.value.map((child) => this.constructObject(child, deep));
  }

  constructMapping(node, deep = false) {
    if (node.kind === 'mapping') this.flattenMapping(node);
    if (node.kind !== 'mapping') {
      throw new ConstructorError(null, null,
        `expected a mapping node, but found ${node.kind}`, node.startMark);
    }
    const mapping = new PyDict();
    for (const [keyNode, valueNode] of node.value) {
      const key = this.constructObject(keyNode, deep);
      if (!isHashable(key)) {
        throw new ConstructorError('while constructing a mapping', node.startMark,
          'found unhashable key', keyNode.startMark);
      }
      const value = this.constructObject(valueNode, deep);
      mapping.set(key, value);
    }
    return mapping;
  }

  constructPairs(node, deep = false) {
