// Event emitter (PyYAML emitter.py). Scalars are handled as arrays of code
// points so that column bookkeeping matches Python's per-character counting.

import { EmitterError } from './errors.mjs';
import { toChars, isLineBreak } from './chars.mjs';
import { pyRepr } from './repr.mjs';

const LINEBR = '\n\x85  ';
const SPACE_LINEBR = ' \n\x85  ';
const NULL_BL_T_LINEBR = '\0 \t\r\n\x85  ';

const DEFAULT_TAG_PREFIXES = new Map([
  ['!', '!'],
  ['tag:yaml.org,2002:', '!!'],
]);

const ESCAPE_REPLACEMENTS = new Map([
  ['\0', '0'], ['\x07', 'a'], ['\x08', 'b'], ['\x09', 't'], ['\x0A', 'n'],
  ['\x0B', 'v'], ['\x0C', 'f'], ['\x0D', 'r'], ['\x1B', 'e'], ['"', '"'],
  ['\\', '\\'], ['\x85', 'N'], ['\xA0', '_'], [' ', 'L'], [' ', 'P'],
]);

class ScalarAnalysis {
  constructor(scalar, empty, multiline, allowFlowPlain, allowBlockPlain,
    allowSingleQuoted, allowDoubleQuoted, allowBlock) {
    this.scalar = scalar;
    this.chars = toChars(scalar);
    this.empty = empty;
    this.multiline = multiline;
    this.allowFlowPlain = allowFlowPlain;
    this.allowBlockPlain = allowBlockPlain;
    this.allowSingleQuoted = allowSingleQuoted;
    this.allowDoubleQuoted = allowDoubleQuoted;
    this.allowBlock = allowBlock;
  }
}

function hexUpper(code, width) {
  let hex = code.toString(16).toUpperCase();
  while (hex.length < width) hex = '0' + hex;
  return hex;
}

function utf8Bytes(ch) {
  return Array.from(new TextEncoder().encode(ch));
}

export class Emitter {
  constructor(options = {}) {
    this.chunks = [];
    this.encoding = null;
    this.states = [];
    this.state = 'expectStreamStart';
    this.events = [];
    this.event = null;
    this.indents = [];
    this.indent = null;
    this.flowLevel = 0;
    this.rootContext = false;
    this.sequenceContext = false;
    this.mappingContext = false;
    this.simpleKeyContext = false;
    this.line = 0;
    this.column = 0;
    this.whitespace = true;
    this.indention = true;
    this.openEnded = false;
    this.canonical = options.canonical || null;
    this.allowUnicode = options.allowUnicode || null;
    this.bestIndent = 2;
    if (options.indent && options.indent > 1 && options.indent < 10) {
      this.bestIndent = options.indent;
    }
    this.bestWidth = 80;
    if (options.width && options.width > this.bestIndent * 2) {
      this.bestWidth = options.width;
    }
    this.bestLineBreak = '\n';
    if (['\r', '\n', '\r\n'].includes(options.lineBreak)) {
      this.bestLineBreak = options.lineBreak;
    }
    this.tagPrefixes = null;
    this.preparedAnchor = null;
    this.preparedTag = null;
    this.analysis = null;
    this.style = null;
  }

  getValue() { return this.chunks.join(''); }

  write(data) { this.chunks.push(data); }

  // --- Event dispatch ----------------------------------------------------

  emit(event) {
    this.events.push(event);
    while (!this.needMoreEvents()) {
      this.event = this.events.shift();
      this[this.state]();
      this.event = null;
    }
  }

  needMoreEvents() {
    if (this.events.length === 0) return true;
    const event = this.events[0];
    if (event.type === 'DocumentStart') return this.needEvents(1);
    if (event.type === 'SequenceStart') return this.needEvents(2);
    if (event.type === 'MappingStart') return this.needEvents(3);
    return false;
  }

  needEvents(count) {
    let level = 0;
    for (const event of this.events.slice(1)) {
      if (event.type === 'DocumentStart' || event.type === 'SequenceStart' ||
          event.type === 'MappingStart') {
        level += 1;
      } else if (event.type === 'DocumentEnd' || event.type === 'SequenceEnd' ||
          event.type === 'MappingEnd') {
        level -= 1;
      } else if (event.type === 'StreamEnd') {
        level = -1;
      }
      if (level < 0) return false;
    }
    return this.events.length < count + 1;
  }

  increaseIndent(flow = false, indentless = false) {
    this.indents.push(this.indent);
    if (this.indent === null) {
      this.indent = flow ? this.bestIndent : 0;
    } else if (!indentless) {
      this.indent += this.bestIndent;
    }
  }

  // --- States ------------------------------------------------------------

  expectStreamStart() {
    if (this.event.type === 'StreamStart') {
      this.writeStreamStart();
      this.state = 'expectFirstDocumentStart';
    } else {
      throw new EmitterError(`expected StreamStartEvent, but got ${this.event.type}`);
    }
  }

  expectNothing() {
    throw new EmitterError(`expected nothing, but got ${this.event.type}`);
  }

  expectFirstDocumentStart() { this.expectDocumentStart(true); }

  expectDocumentStart(first = false) {
    if (this.event.type === 'DocumentStart') {
      if ((this.event.version || this.event.tags) && this.openEnded) {
        this.writeIndicator('...', true);
        this.writeIndent();
      }
      if (this.event.version) {
        this.writeVersionDirective(this.prepareVersion(this.event.version));
      }
      this.tagPrefixes = new Map(DEFAULT_TAG_PREFIXES);
      if (this.event.tags) {
        const handles = Array.from(this.event.tags.keys()).sort();
        for (const handle of handles) {
          const prefix = this.event.tags.get(handle);
          this.tagPrefixes.set(prefix, handle);
          this.writeTagDirective(this.prepareTagHandle(handle),
            this.prepareTagPrefix(prefix));
        }
      }
      const implicit = first && !this.event.explicit && !this.canonical &&
        !this.event.version && !this.event.tags && !this.checkEmptyDocument();
      if (!implicit) {
        this.writeIndent();
        this.writeIndicator('---', true);
        if (this.canonical) this.writeIndent();
      }
      this.state = 'expectDocumentRoot';
    } else if (this.event.type === 'StreamEnd') {
      if (this.openEnded) {
        this.writeIndicator('...', true);
        this.writeIndent();
      }
      this.writeStreamEnd();
      this.state = 'expectNothing';
    } else {
      throw new EmitterError(
        `expected DocumentStartEvent, but got ${this.event.type}`);
    }
  }

  expectDocumentEnd() {
    if (this.event.type === 'DocumentEnd') {
      this.writeIndent();
      if (this.event.explicit) {
        this.writeIndicator('...', true);
        this.writeIndent();
      }
      this.state = 'expectDocumentStart';
    } else {
      throw new EmitterError(
        `expected DocumentEndEvent, but got ${this.event.type}`);
    }
  }

  expectDocumentRoot() {
    this.states.push('expectDocumentEnd');
    this.expectNode(true, false, false, false);
  }

  expectNode(root = false, sequence = false, mapping = false, simpleKey = false) {
    this.rootContext = root;
    this.sequenceContext = sequence;
    this.mappingContext = mapping;
    this.simpleKeyContext = simpleKey;
    if (this.event.type === 'Alias') {
      this.expectAlias();
    } else if (this.event.type === 'Scalar' || this.event.type === 'SequenceStart' ||
        this.event.type === 'MappingStart') {
      this.processAnchor('&');
      this.processTag();
      if (this.event.type === 'Scalar') {
        this.expectScalar();
      } else if (this.event.type === 'SequenceStart') {
        if (this.flowLevel || this.canonical || this.event.flowStyle ||
            this.checkEmptySequence()) {
          this.expectFlowSequence();
        } else {
          this.expectBlockSequence();
        }
      } else {
        if (this.flowLevel || this.canonical || this.event.flowStyle ||
            this.checkEmptyMapping()) {
          this.expectFlowMapping();
        } else {
          this.expectBlockMapping();
        }
      }
    } else {
      throw new EmitterError(`expected NodeEvent, but got ${this.event.type}`);
    }
  }

  expectAlias() {
    if (this.event.anchor === null) {
      throw new EmitterError('anchor is not specified for alias');
    }
    this.processAnchor('*');
    this.state = this.states.pop();
  }

  expectScalar() {
    this.increaseIndent(true);
    this.processScalar();
    this.indent = this.indents.pop();
    this.state = this.states.pop();
  }

  // --- Flow collections --------------------------------------------------

  expectFlowSequence() {
    this.writeIndicator('[', true, true);
    this.flowLevel += 1;
    this.increaseIndent(true);
    this.state = 'expectFirstFlowSequenceItem';
  }

  expectFirstFlowSequenceItem() {
    if (this.event.type === 'SequenceEnd') {
      this.indent = this.indents.pop();
      this.flowLevel -= 1;
      this.writeIndicator(']', false);
      this.state = this.states.pop();
    } else {
      if (this.canonical || this.column > this.bestWidth) this.writeIndent();
      this.states.push('expectFlowSequenceItem');
      this.expectNode(false, true, false, false);
    }
  }

  expectFlowSequenceItem() {
    if (this.event.type === 'SequenceEnd') {
      this.indent = this.indents.pop();
      this.flowLevel -= 1;
      if (this.canonical) {
        this.writeIndicator(',', false);
        this.writeIndent();
      }
      this.writeIndicator(']', false);
      this.state = this.states.pop();
    } else {
      this.writeIndicator(',', false);
      if (this.canonical || this.column > this.bestWidth) this.writeIndent();
      this.states.push('expectFlowSequenceItem');
      this.expectNode(false, true, false, false);
    }
  }

  expectFlowMapping() {
    this.writeIndicator('{', true, true);
    this.flowLevel += 1;
    this.increaseIndent(true);
    this.state = 'expectFirstFlowMappingKey';
  }

  expectFirstFlowMappingKey() {
    if (this.event.type === 'MappingEnd') {
      this.indent = this.indents.pop();
      this.flowLevel -= 1;
      this.writeIndicator('}', false);
      this.state = this.states.pop();
    } else {
      if (this.canonical || this.column > this.bestWidth) this.writeIndent();
      if (!this.canonical && this.checkSimpleKey()) {
        this.states.push('expectFlowMappingSimpleValue');
        this.expectNode(false, false, true, true);
      } else {
        this.writeIndicator('?', true);
        this.states.push('expectFlowMappingValue');
        this.expectNode(false, false, true, false);
      }
    }
  }

  expectFlowMappingKey() {
    if (this.event.type === 'MappingEnd') {
      this.indent = this.indents.pop();
      this.flowLevel -= 1;
      if (this.canonical) {
        this.writeIndicator(',', false);
        this.writeIndent();
      }
      this.writeIndicator('}', false);
      this.state = this.states.pop();
    } else {
      this.writeIndicator(',', false);
      if (this.canonical || this.column > this.bestWidth) this.writeIndent();
      if (!this.canonical && this.checkSimpleKey()) {
        this.states.push('expectFlowMappingSimpleValue');
        this.expectNode(false, false, true, true);
      } else {
        this.writeIndicator('?', true);
        this.states.push('expectFlowMappingValue');
        this.expectNode(false, false, true, false);
      }
    }
  }

  expectFlowMappingSimpleValue() {
    this.writeIndicator(':', false);
    this.states.push('expectFlowMappingKey');
    this.expectNode(false, false, true, false);
  }

  expectFlowMappingValue() {
    if (this.canonical || this.column > this.bestWidth) this.writeIndent();
    this.writeIndicator(':', true);
    this.states.push('expectFlowMappingKey');
    this.expectNode(false, false, true, false);
  }

  // --- Block collections -------------------------------------------------

  expectBlockSequence() {
    const indentless = this.mappingContext && !this.indention;
    this.increaseIndent(false, indentless);
    this.state = 'expectFirstBlockSequenceItem';
  }

  expectFirstBlockSequenceItem() { this.expectBlockSequenceItem(true); }

  expectBlockSequenceItem(first = false) {
    if (!first && this.event.type === 'SequenceEnd') {
      this.indent = this.indents.pop();
      this.state = this.states.pop();
    } else {
      this.writeIndent();
      this.writeIndicator('-', true, false, true);
      this.states.push('expectBlockSequenceItem');
      this.expectNode(false, true, false, false);
    }
  }

  expectBlockMapping() {
    this.increaseIndent(false);
    this.state = 'expectFirstBlockMappingKey';
  }

  expectFirstBlockMappingKey() { this.expectBlockMappingKey(true); }

  expectBlockMappingKey(first = false) {
    if (!first && this.event.type === 'MappingEnd') {
      this.indent = this.indents.pop();
      this.state = this.states.pop();
    } else {
      this.writeIndent();
      if (this.checkSimpleKey()) {
        this.states.push('expectBlockMappingSimpleValue');
        this.expectNode(false, false, true, true);
      } else {
        this.writeIndicator('?', true, false, true);
        this.states.push('expectBlockMappingValue');
        this.expectNode(false, false, true, false);
      }
    }
  }

  expectBlockMappingSimpleValue() {
    this.writeIndicator(':', false);
    this.states.push('expectBlockMappingKey');
    this.expectNode(false, false, true, false);
  }

  expectBlockMappingValue() {
    this.writeIndent();
    this.writeIndicator(':', true, false, true);
    this.states.push('expectBlockMappingKey');
    this.expectNode(false, false, true, false);
  }

  // --- Checkers ----------------------------------------------------------

  checkEmptySequence() {
    return this.event.type === 'SequenceStart' && this.events.length > 0 &&
      this.events[0].type === 'SequenceEnd';
  }

  checkEmptyMapping() {
    return this.event.type === 'MappingStart' && this.events.length > 0 &&
      this.events[0].type === 'MappingEnd';
  }

  checkEmptyDocument() {
    if (this.event.type !== 'DocumentStart' || this.events.length === 0) {
      return false;
    }
    const event = this.events[0];
    return event.type === 'Scalar' && event.anchor === null &&
      event.tag === null && Boolean(event.implicit) && event.value === '';
  }

  checkSimpleKey() {
    let length = 0;
    if ((this.event.type === 'Scalar' || this.event.type === 'SequenceStart' ||
         this.event.type === 'MappingStart' || this.event.type === 'Alias') &&
        this.event.anchor !== null && this.event.anchor !== undefined) {
      if (this.preparedAnchor === null) {
        this.preparedAnchor = this.prepareAnchor(this.event.anchor);
      }
      length += toChars(this.preparedAnchor).length;
    }
    if ((this.event.type === 'Scalar' || this.event.type === 'SequenceStart' ||
         this.event.type === 'MappingStart') &&
        this.event.tag !== null && this.event.tag !== undefined) {
      if (this.preparedTag === null) {
        this.preparedTag = this.prepareTag(this.event.tag);
      }
      length += toChars(this.preparedTag).length;
    }
    if (this.event.type === 'Scalar') {
      if (this.analysis === null) {
        this.analysis = this.analyzeScalar(this.event.value);
      }
      length += this.analysis.chars.length;
    }
    return length < 128 && (this.event.type === 'Alias' ||
      (this.event.type === 'Scalar' && !this.analysis.empty &&
        !this.analysis.multiline) ||
      this.checkEmptySequence() || this.checkEmptyMapping());
  }

  // --- Anchor / tag / scalar processors ----------------------------------

  processAnchor(indicator) {
    if (this.event.anchor === null || this.event.anchor === undefined) {
      this.preparedAnchor = null;
      return;
    }
    if (this.preparedAnchor === null) {
      this.preparedAnchor = this.prepareAnchor(this.event.anchor);
    }
    if (this.preparedAnchor) {
      this.writeIndicator(indicator + this.preparedAnchor, true);
    }
    this.preparedAnchor = null;
  }

  processTag() {
    let tag = this.event.tag;
    if (this.event.type === 'Scalar') {
      if (this.style === null) this.style = this.chooseScalarStyle();
      if ((!this.canonical || tag === null) &&
          ((this.style === '' && this.event.implicit[0]) ||
           (this.style !== '' && this.event.implicit[1]))) {
        this.preparedTag = null;
        return;
      }
      if (this.event.implicit[0] && tag === null) {
        tag = '!';
        this.preparedTag = null;
      }
    } else if ((!this.canonical || tag === null) && this.event.implicit) {
      this.preparedTag = null;
      return;
    }
    if (tag === null) throw new EmitterError('tag is not specified');
    if (this.preparedTag === null) this.preparedTag = this.prepareTag(tag);
    if (this.preparedTag) this.writeIndicator(this.preparedTag, true);
    this.preparedTag = null;
  }

  chooseScalarStyle() {
    if (this.analysis === null) this.analysis = this.analyzeScalar(this.event.value);
    if (this.event.style === '"' || this.canonical) return '"';
    if (!this.event.style && this.event.implicit[0]) {
      if (!(this.simpleKeyContext && (this.analysis.empty || this.analysis.multiline)) &&
          ((this.flowLevel && this.analysis.allowFlowPlain) ||
           (!this.flowLevel && this.analysis.allowBlockPlain))) {
        return '';
      }
    }
    if (this.event.style && (this.event.style === '|' || this.event.style === '>')) {
      if (!this.flowLevel && !this.simpleKeyContext && this.analysis.allowBlock) {
        return this.event.style;
      }
    }
    if (!this.event.style || this.event.style === "'") {
      if (this.analysis.allowSingleQuoted &&
          !(this.simpleKeyContext && this.analysis.multiline)) {
        return "'";
      }
    }
    return '"';
  }

  processScalar() {
    if (this.analysis === null) this.analysis = this.analyzeScalar(this.event.value);
    if (this.style === null) this.style = this.chooseScalarStyle();
    const split = !this.simpleKeyContext;
    if (this.style === '"') this.writeDoubleQuoted(this.analysis.chars, split);
    else if (this.style === "'") this.writeSingleQuoted(this.analysis.chars, split);
    else if (this.style === '>') this.writeFolded(this.analysis.chars);
    else if (this.style === '|') this.writeLiteral(this.analysis.chars);
    else this.writePlain(this.analysis.chars, split);
    this.analysis = null;
    this.style = null;
  }

  // --- Analyzers ---------------------------------------------------------

  prepareVersion(version) {
    const [major, minor] = version;
    if (major !== 1) {
      throw new EmitterError('unsupported YAML version: ' + major + '.' + minor);
    }
    return `${major}.${minor}`;
  }

  prepareTagHandle(handle) {
    if (!handle) throw new EmitterError('tag handle must not be empty');
    if (handle[0] !== '!' || handle[handle.length - 1] !== '!') {
      throw new EmitterError(
        `tag handle must start and end with '!': ${pyRepr(handle)}`);
    }
    for (const ch of handle.slice(1, -1)) {
      if (!((ch >= '0' && ch <= '9') || (ch >= 'A' && ch <= 'Z') ||
            (ch >= 'a' && ch <= 'z') || ch === '-' || ch === '_')) {
        throw new EmitterError(
          `invalid character ${pyRepr(ch)} in the tag handle: ${pyRepr(handle)}`);
      }
    }
    return handle;
  }

  prepareTagPrefix(prefix) {
    if (!prefix) throw new EmitterError('tag prefix must not be empty');
    const chunks = [];
    const chars = toChars(prefix);
    let start = 0;
    let end = chars[0] === '!' ? 1 : 0;
    while (end < chars.length) {
      const ch = chars[end];
      if ((ch >= '0' && ch <= '9') || (ch >= 'A' && ch <= 'Z') ||
          (ch >= 'a' && ch <= 'z') || "-;/?!:@&=+$,_.~*'()[]".includes(ch)) {
        end += 1;
      } else {
        if (start < end) chunks.push(chars.slice(start, end).join(''));
        start = end + 1;
        end = start;
        for (const byte of utf8Bytes(ch)) chunks.push('%' + hexUpper(byte, 2));
      }
    }
    if (start < end) chunks.push(chars.slice(start, end).join(''));
    return chunks.join('');
  }

  prepareTag(tag) {
    if (!tag) throw new EmitterError('tag must not be empty');
    if (tag === '!') return tag;
    let handle = null;
    let suffix = tag;
    const prefixes = Array.from(this.tagPrefixes.keys()).sort();
    for (const prefix of prefixes) {
      if (tag.startsWith(prefix) && (prefix === '!' || prefix.length < tag.length)) {
        handle = this.tagPrefixes.get(prefix);
        suffix = tag.slice(prefix.length);
      }
    }
    const chunks = [];
    const chars = toChars(suffix);
    let start = 0;
    let end = 0;
    while (end < chars.length) {
      const ch = chars[end];
      if ((ch >= '0' && ch <= '9') || (ch >= 'A' && ch <= 'Z') ||
          (ch >= 'a' && ch <= 'z') || "-;/?:@&=+$,_.~*'()[]".includes(ch) ||
          (ch === '!' && handle !== '!')) {
        end += 1;
      } else {
        if (start < end) chunks.push(chars.slice(start, end).join(''));
        start = end + 1;
        end = start;
        for (const byte of utf8Bytes(ch)) chunks.push('%' + hexUpper(byte, 2));
      }
    }
    if (start < end) chunks.push(chars.slice(start, end).join(''));
    const suffixText = chunks.join('');
    if (handle) return handle + suffixText;
    return `!<${suffixText}>`;
  }

  prepareAnchor(anchor) {
    if (!anchor) throw new EmitterError('anchor must not be empty');
    for (const ch of anchor) {
      if (!((ch >= '0' && ch <= '9') || (ch >= 'A' && ch <= 'Z') ||
            (ch >= 'a' && ch <= 'z') || ch === '-' || ch === '_')) {
        throw new EmitterError(
          `invalid character ${pyRepr(ch)} in the anchor: ${pyRepr(anchor)}`);
      }
    }
    return anchor;
  }

  analyzeScalar(scalar) {
    if (scalar === '') {
      return new ScalarAnalysis(scalar, true, false, false, true, true, true, false);
    }
    const chars = toChars(scalar);
    let blockIndicators = false;
    let flowIndicators = false;
    let lineBreaks = false;
    let specialCharacters = false;

    let leadingSpace = false;
    let leadingBreak = false;
    let trailingSpace = false;
    let trailingBreak = false;
    let breakSpace = false;
    let spaceBreak = false;

    const head = chars.slice(0, 3).join('');
    if (head === '---' || head === '...') {
      blockIndicators = true;
      flowIndicators = true;
    }

    let precededByWhitespace = true;
    let followedByWhitespace = chars.length === 1 ||
      NULL_BL_T_LINEBR.includes(chars[1]);
    let previousSpace = false;
    let previousBreak = false;

    let index = 0;
    while (index < chars.length) {
      const ch = chars[index];
      if (index === 0) {
        if ('#,[]{}&*!|>\'"%@`'.includes(ch)) {
          flowIndicators = true;
          blockIndicators = true;
        }
        if (ch === '?' || ch === ':') {
          flowIndicators = true;
          if (followedByWhitespace) blockIndicators = true;
        }
        if (ch === '-' && followedByWhitespace) {
          flowIndicators = true;
          blockIndicators = true;
        }
      } else {
        if (',?[]{}'.includes(ch)) flowIndicators = true;
        if (ch === ':') {
          flowIndicators = true;
          if (followedByWhitespace) blockIndicators = true;
        }
        if (ch === '#' && precededByWhitespace) {
          flowIndicators = true;
          blockIndicators = true;
        }
      }

      if (isLineBreak(ch)) lineBreaks = true;
      if (!(ch === '\n' || (ch >= '\x20' && ch <= '\x7E'))) {
        const code = ch.codePointAt(0);
        const printable = code === 0x85 ||
          (code >= 0xa0 && code <= 0xd7ff) ||
          (code >= 0xe000 && code <= 0xfffd) ||
          (code >= 0x10000 && code < 0x10ffff);
        if (printable && code !== 0xfeff) {
          if (!this.allowUnicode) specialCharacters = true;
        } else {
          specialCharacters = true;
        }
      }

      if (ch === ' ') {
        if (index === 0) leadingSpace = true;
        if (index === chars.length - 1) trailingSpace = true;
        if (previousBreak) breakSpace = true;
        previousSpace = true;
        previousBreak = false;
      } else if (isLineBreak(ch)) {
        if (index === 0) leadingBreak = true;
        if (index === chars.length - 1) trailingBreak = true;
        if (previousSpace) spaceBreak = true;
        previousSpace = false;
        previousBreak = true;
      } else {
        previousSpace = false;
        previousBreak = false;
      }

      index += 1;
      precededByWhitespace = NULL_BL_T_LINEBR.includes(ch);
      followedByWhitespace = index + 1 >= chars.length ||
        NULL_BL_T_LINEBR.includes(chars[index + 1]);
    }

    let allowFlowPlain = true;
    let allowBlockPlain = true;
    let allowSingleQuoted = true;
    const allowDoubleQuoted = true;
    let allowBlock = true;

    if (leadingSpace || leadingBreak || trailingSpace || trailingBreak) {
      allowFlowPlain = false;
      allowBlockPlain = false;
    }
    if (trailingSpace) allowBlock = false;
    if (breakSpace) {
      allowFlowPlain = false;
      allowBlockPlain = false;
      allowSingleQuoted = false;
    }
    if (spaceBreak || specialCharacters) {
      allowFlowPlain = false;
      allowBlockPlain = false;
      allowSingleQuoted = false;
      allowBlock = false;
    }
    if (lineBreaks) {
      allowFlowPlain = false;
      allowBlockPlain = false;
    }
    if (flowIndicators) allowFlowPlain = false;
    if (blockIndicators) allowBlockPlain = false;

    return new ScalarAnalysis(scalar, false, lineBreaks, allowFlowPlain,
      allowBlockPlain, allowSingleQuoted, allowDoubleQuoted, allowBlock);
  }

  // --- Writers -----------------------------------------------------------

  writeStreamStart() { /* no BOM: the output is a str, not bytes */ }
  writeStreamEnd() { /* nothing to flush */ }

  writeIndicator(indicator, needWhitespace, whitespace = false, indention = false) {
    const data = (this.whitespace || !needWhitespace) ? indicator : ' ' + indicator;
    this.whitespace = whitespace;
    this.indention = this.indention && indention;
    this.column += toChars(data).length;
    this.openEnded = false;
    this.write(data);
  }

  writeIndent() {
    const indent = this.indent || 0;
    if (!this.indention || this.column > indent ||
        (this.column === indent && !this.whitespace)) {
      this.writeLineBreak();
    }
    if (this.column < indent) {
      this.whitespace = true;
      const data = ' '.repeat(indent - this.column);
      this.column = indent;
      this.write(data);
    }
  }

  writeLineBreak(data = null) {
    const text = data === null ? this.bestLineBreak : data;
    this.whitespace = true;
    this.indention = true;
    this.line += 1;
    this.column = 0;
    this.write(text);
  }

  writeVersionDirective(versionText) {
    this.write(`%YAML ${versionText}`);
    this.writeLineBreak();
  }

  writeTagDirective(handleText, prefixText) {
    this.write(`%TAG ${handleText} ${prefixText}`);
    this.writeLineBreak();
  }

  writeSingleQuoted(chars, split = true) {
    this.writeIndicator("'", true);
    let spaces = false;
    let breaks = false;
    let start = 0;
    let end = 0;
    while (end <= chars.length) {
      let ch = null;
      if (end < chars.length) ch = chars[end];
      if (spaces) {
        if (ch === null || ch !== ' ') {
          if (start + 1 === end && this.column > this.bestWidth && split &&
              start !== 0 && end !== chars.length) {
            this.writeIndent();
          } else {
            const data = chars.slice(start, end).join('');
            this.column += end - start;
            this.write(data);
          }
          start = end;
        }
      } else if (breaks) {
        if (ch === null || !LINEBR.includes(ch)) {
          if (chars[start] === '\n') this.writeLineBreak();
          for (const br of chars.slice(start, end)) {
            if (br === '\n') this.writeLineBreak();
            else this.writeLineBreak(br);
          }
          this.writeIndent();
          start = end;
        }
      } else if (ch === null || SPACE_LINEBR.includes(ch) || ch === "'") {
        if (start < end) {
          const data = chars.slice(start, end).join('');
          this.column += end - start;
          this.write(data);
          start = end;
        }
      }
      if (ch === "'") {
        this.column += 2;
        this.write("''");
        start = end + 1;
      }
      if (ch !== null) {
        spaces = ch === ' ';
        breaks = LINEBR.includes(ch);
      }
      end += 1;
    }
    this.writeIndicator("'", false);
  }

  writeDoubleQuoted(chars, split = true) {
    this.writeIndicator('"', true);
    let start = 0;
    let end = 0;
    while (end <= chars.length) {
      let ch = null;
      if (end < chars.length) ch = chars[end];
      if (ch === null || '"\\\x85  ﻿'.includes(ch) ||
          !((ch >= '\x20' && ch <= '\x7E') ||
            (this.allowUnicode && isUnicodePrintable(ch)))) {
        if (start < end) {
          const data = chars.slice(start, end).join('');
          this.column += end - start;
          this.write(data);
          start = end;
        }
        if (ch !== null) {
          let data;
          const code = ch.codePointAt(0);
          if (ESCAPE_REPLACEMENTS.has(ch)) {
            data = '\\' + ESCAPE_REPLACEMENTS.get(ch);
          } else if (code <= 0xff) {
            data = '\\x' + hexUpper(code, 2);
          } else if (code <= 0xffff) {
            data = '\\u' + hexUpper(code, 4);
          } else {
            data = '\\U' + hexUpper(code, 8);
          }
          this.column += data.length;
          this.write(data);
          start = end + 1;
        }
      }
      if (end > 0 && end < chars.length - 1 && (ch === ' ' || start >= end) &&
          this.column + (end - start) > this.bestWidth && split) {
        let data = chars.slice(start, end).join('') + '\\';
        if (start < end) start = end;
        this.column += toChars(data).length;
        this.write(data);
        this.writeIndent();
        this.whitespace = false;
        this.indention = false;
        if (chars[start] === ' ') {
          data = '\\';
          this.column += 1;
          this.write(data);
        }
      }
      end += 1;
    }
    this.writeIndicator('"', false);
  }

  determineBlockHints(chars) {
    let hints = '';
    if (chars.length) {
      if (SPACE_LINEBR.includes(chars[0])) hints += String(this.bestIndent);
      const last = chars[chars.length - 1];
      if (!LINEBR.includes(last)) {
        hints += '-';
      } else if (chars.length === 1 || LINEBR.includes(chars[chars.length - 2])) {
        hints += '+';
      }
    }
    return hints;
  }

  writeFolded(chars) {
    const hints = this.determineBlockHints(chars);
    this.writeIndicator('>' + hints, true);
    if (hints.endsWith('+')) this.openEnded = true;
    this.writeLineBreak();
    let leadingSpace = true;
    let spaces = false;
    let breaks = true;
    let start = 0;
    let end = 0;
    while (end <= chars.length) {
      let ch = null;
      if (end < chars.length) ch = chars[end];
      if (breaks) {
        if (ch === null || !LINEBR.includes(ch)) {
          if (!leadingSpace && ch !== null && ch !== ' ' && chars[start] === '\n') {
            this.writeLineBreak();
          }
          leadingSpace = ch === ' ';
          for (const br of chars.slice(start, end)) {
            if (br === '\n') this.writeLineBreak();
            else this.writeLineBreak(br);
          }
          if (ch !== null) this.writeIndent();
          start = end;
        }
      } else if (spaces) {
        if (ch !== ' ') {
          if (start + 1 === end && this.column > this.bestWidth) {
            this.writeIndent();
          } else {
            const data = chars.slice(start, end).join('');
            this.column += end - start;
            this.write(data);
          }
          start = end;
        }
      } else if (ch === null || SPACE_LINEBR.includes(ch)) {
        const data = chars.slice(start, end).join('');
        this.column += end - start;
        this.write(data);
        if (ch === null) this.writeLineBreak();
        start = end;
      }
      if (ch !== null) {
        breaks = LINEBR.includes(ch);
        spaces = ch === ' ';
      }
      end += 1;
    }
  }

  writeLiteral(chars) {
    const hints = this.determineBlockHints(chars);
    this.writeIndicator('|' + hints, true);
    if (hints.endsWith('+')) this.openEnded = true;
    this.writeLineBreak();
    let breaks = true;
    let start = 0;
    let end = 0;
    while (end <= chars.length) {
      let ch = null;
      if (end < chars.length) ch = chars[end];
      if (breaks) {
        if (ch === null || !LINEBR.includes(ch)) {
          for (const br of chars.slice(start, end)) {
            if (br === '\n') this.writeLineBreak();
            else this.writeLineBreak(br);
          }
          if (ch !== null) this.writeIndent();
          start = end;
        }
      } else if (ch === null || LINEBR.includes(ch)) {
        this.write(chars.slice(start, end).join(''));
        if (ch === null) this.writeLineBreak();
        start = end;
      }
      if (ch !== null) breaks = LINEBR.includes(ch);
      end += 1;
    }
  }

  writePlain(chars, split = true) {
    if (this.rootContext) this.openEnded = true;
    if (chars.length === 0) return;
    if (!this.whitespace) {
      this.column += 1;
